// Unified three-tier routing engine (architecture inspired by ordo-systems/keen-proxy):
// L1 Direct RU -> WAN bypassing Zapret+VPN, L2 Zapret nfqws -> direct WAN,
// L3 everything else -> sing-box VPN by subscription with failover.
// The nft/dnsmasq/iproute artifacts are generated by the tested TS engine
// (src/services/routing-engine), staged via tiers_stage and applied on the
// router by tiers_commit which re-validates (nft -c, sh -n) and self-heals
// routes after netifd. sing-box config is regenerated router-side from tiers.json.
import React, { useEffect, useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { ubusClient } from "@/lib/ubus-client";
import { useI18nStore } from "@/store/i18n-store";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Globe, Shield, Zap, Server, RefreshCw, Play, Trash2, CheckCircle2, XCircle, AlertTriangle } from "lucide-react";
import {
  defaultConfig, validateConfig, genTierNft, genDnsmasqTiers, genIprouteScript,
  type TierConfig,
} from "@/services/routing-engine";

const lines = (s: string): string[] => s.split("\n").map((x) => x.trim().toLowerCase().replace(/\.+$/, "")).filter(Boolean);
const csv = (s: string): string[] => s.split(/[,;\s]+/).map((x) => x.trim()).filter(Boolean);

export const RoutingEngineView: React.FC = () => {
  const { lang } = useI18nStore();
  const isRu = lang === "ru";
  const L = (ru: string, en: string) => (isRu ? ru : en);
  const qc = useQueryClient();

  const [draft, setDraft] = useState<TierConfig>(() => defaultConfig());
  const [withAntizapret, setWithAntizapret] = useState(true);
  const [loaded, setLoaded] = useState(false);
  const [msg, setMsg] = useState<{ text: string; error?: boolean } | null>(null);
  const [errs, setErrs] = useState<string[]>([]);

  const { data: st } = useQuery({
    queryKey: ["tiers-status"],
    queryFn: () => ubusClient.getTiersStatus(),
    refetchInterval: 15000,
  });
  const { data: cfgData } = useQuery({
    queryKey: ["tiers-config"],
    queryFn: () => ubusClient.getTiersConfig(),
  });

  useEffect(() => {
    if (!cfgData?.config || loaded) return;
    try {
      const parsed = JSON.parse(cfgData.config) as TierConfig;
      if (parsed?.version) {
        setDraft({ ...defaultConfig(), ...parsed });
        setLoaded(true);
      }
    } catch { /* defaults stay */ }
  }, [cfgData, loaded]);

  const applyMut = useMutation({
    mutationFn: async () => {
      const cfg: TierConfig = {
        ...draft,
        tier1: { ...draft.tier1, domains: lines(draft.tier1.domains.join("\n")), networks: csv(draft.tier1.networks.join(" ")) },
        tier2: { ...draft.tier2, domains: lines(draft.tier2.domains.join("\n")) },
        tier3ExtraDomains: lines(draft.tier3ExtraDomains.join("\n")),
      };
      const problems = validateConfig(cfg);
      if (problems.length > 0) {
        setErrs(problems);
        throw new Error(isRu ? "Конфиг не прошёл самопроверку (см. список)" : "Config failed self-validation");
      }
      const nodeServers = csv(st?.node_servers || "");
      if (cfg.proxyEnabled && nodeServers.length === 0) {
        setErrs([isRu ? "Нет узлов подписки — сначала обновите подписку" : "No subscription nodes — refresh the subscription first"]);
        throw new Error(isRu ? "Нет активных узлов" : "No active nodes");
      }
      setErrs([]);
      return ubusClient.tiersDeploy({
        nft: genTierNft({ cfg, nodeServers }),
        dnsmasq: genDnsmasqTiers(cfg),
        iproute: genIprouteScript(cfg),
        tierConfigJson: JSON.stringify({ ...cfg, withAntizapret }),
      });
    },
    onSuccess: (r) => {
      setMsg({ text: r.message + ` (nft:${r.nft_applied ? "ok" : "FAIL"} route:${r.route_applied ? "ok" : "FAIL"} dns:${r.dns_hook_applied ? "ok" : "FAIL"})` });
      void qc.invalidateQueries({ queryKey: ["tiers-status"] });
    },
    onError: (e: Error) => setMsg({ text: e.message, error: true }),
  });

  const disableMut = useMutation({
    mutationFn: () => ubusClient.tiersDisable(),
    onSuccess: (r) => { setMsg({ text: r.message }); void qc.invalidateQueries({ queryKey: ["tiers-status"] }); },
    onError: (e: Error) => setMsg({ text: e.message, error: true }),
  });

  const refreshMut = useMutation({
    mutationFn: async () => {
      const a = await ubusClient.subRefresh();
      const b = await ubusClient.nodeBalancerRun();
      return { a, b };
    },
    onSuccess: () => {
      setMsg({ text: L("Подписка обновлена, балансер запущен", "Subscription refreshed, balancer started") });
      void qc.invalidateQueries({ queryKey: ["tiers-status"] });
    },
    onError: (e: Error) => setMsg({ text: e.message, error: true }),
  });

  const applied = !!st?.nft_live;
  const setText = (patch: Partial<TierConfig>) => setDraft((d) => ({ ...d, ...patch }));

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle className="flex items-center gap-2">
            <Globe className="h-5 w-5" />
            {L("Единый движок маршрутизации", "Unified routing engine")}
            {applied
              ? <Badge variant="outline" className="text-green-600 border-green-600"><CheckCircle2 className="h-3 w-3 mr-1" />{L("активен", "active")}</Badge>
              : <Badge variant="outline" className="text-yellow-600 border-yellow-600"><AlertTriangle className="h-3 w-3 mr-1" />{L("не применён", "not applied")}</Badge>}
          </CardTitle>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" onClick={() => refreshMut.mutate()} disabled={refreshMut.isPending}>
              <RefreshCw className={`h-4 w-4 mr-1 ${refreshMut.isPending ? "animate-spin" : ""}`} />{L("Обновить подписку и ноды", "Refresh subscription & nodes")}
            </Button>
            <Button size="sm" onClick={() => applyMut.mutate()} disabled={applyMut.isPending || !st}>
              <Play className="h-4 w-4 mr-1" />{applyMut.isPending ? L("Применяю…", "Applying…") : L("Применить движок", "Apply engine")}
            </Button>
            {applied && (
              <Button variant="destructive" size="sm" onClick={() => disableMut.mutate()} disabled={disableMut.isPending}>
                <Trash2 className="h-4 w-4 mr-1" />{L("Снять", "Disable")}
              </Button>
            )}
          </div>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
            <div className="min-w-0">
              <div className="text-muted-foreground text-xs">{L("Активный узел", "Active node")}</div>
              <div className="font-mono truncate" title={st?.active_name}>{st?.active_name || (st?.node_count ? L("нет активного", "none active") : L("нет узлов", "no nodes"))}</div>
              <div className="text-xs text-muted-foreground truncate">{st?.active_server ? `${st.active_server}:${st.active_port} · ${st.active_protocol}` : ""}</div>
            </div>
            <div>
              <div className="text-muted-foreground text-xs">{L("Задержка/скорость", "Latency/speed")}</div>
              <div>{st?.active_latency_ms ? `${st.active_latency_ms} мс` : "—"}</div>
              <div className="text-xs text-muted-foreground">{st?.active_updated || ""}</div>
            </div>
            <div>
              <div className="text-muted-foreground text-xs">sing-box / nfqws</div>
              <div className="flex gap-2">
                <span className={st?.singbox_running ? "text-green-600" : "text-red-600"}>
                  {st?.singbox_running ? <CheckCircle2 className="h-4 w-4 inline" /> : <XCircle className="h-4 w-4 inline" />} VPN
                </span>
                <span className={st?.nfqws_running ? "text-green-600" : "text-yellow-600"}>
                  {st?.nfqws_running ? <CheckCircle2 className="h-4 w-4 inline" /> : <AlertTriangle className="h-4 w-4 inline" />} Zapret
                </span>
              </div>
            </div>
            <div>
              <div className="text-muted-foreground text-xs">{L("Ядро на роутере", "Router kernel state")}</div>
              <div className="text-xs">
                nft: {st?.nft_live ? "ok" : "no"} · routes: {st?.routes_installed ? "ok" : "no"} · dns: {st?.dns_hook ? "ok" : "no"} · cron: {st?.cron ?? 0}
              </div>
              <div className="text-xs text-muted-foreground">{L("узлов в подписке: ", "nodes: ")}{st?.node_count ?? 0}</div>
            </div>
          </div>
          {msg && <div className={`text-sm ${msg.error ? "text-red-600" : "text-green-600"}`}>{msg.text}</div>}
          {errs.length > 0 && (
            <div className="text-sm text-red-600 bg-red-50 dark:bg-red-950/30 rounded p-2 space-y-1">
              {errs.map((e, i) => <div key={i}>• {e}</div>)}
            </div>
          )}
        </CardContent>
      </Card>

      <div className="grid md:grid-cols-3 gap-4">
        <Card>
          <CardHeader><CardTitle className="flex items-center gap-2 text-base"><Shield className="h-4 w-4 text-green-600" />{L("1. Напрямую (РФ)", "1. Direct (RU)")}</CardTitle></CardHeader>
          <CardContent className="space-y-2 text-sm">
            <p className="text-muted-foreground text-xs">{L("geoip:ru, geosite:category-ru, банки, госуслуги, .ru/.рф/.su — жёстко через WAN, мимо Zapret и VPN.", "geoip:ru, geosite:category-ru, banks, gov, .ru/.рф/.su — hard direct via WAN, bypassing Zapret and VPN.")}</p>
            <label className="text-xs text-muted-foreground">{L("Доп. домены (по одному)", "Extra domains (one per line)")}</label>
            <textarea className="w-full h-24 rounded border bg-background p-2 font-mono text-xs" value={draft.tier1.domains.join("\n")} onChange={(e) => setText({ tier1: { ...draft.tier1, domains: e.target.value.split("\n") } })} />
            <label className="text-xs text-muted-foreground">{L("Доп. подсети CIDR", "Extra CIDR networks")}</label>
            <textarea className="w-full h-16 rounded border bg-background p-2 font-mono text-xs" value={draft.tier1.networks.join("\n")} onChange={(e) => setText({ tier1: { ...draft.tier1, networks: e.target.value.split("\n") } })} />
          </CardContent>
        </Card>

        <Card>
          <CardHeader><CardTitle className="flex items-center gap-2 text-base"><Zap className="h-4 w-4 text-yellow-500" />{L("2. Zapret (YouTube и список пользователя)", "2. Zapret (YouTube + user list)")}</CardTitle></CardHeader>
          <CardContent className="space-y-2 text-sm">
            <p className="text-muted-foreground text-xs">{L("Эти домены резолвятся напрямую и идут в WAN через очередь nfqws — мимо VPN. Discord сюда не входит: на этой линии ТСПУ режет его при любой стратегии nfqws (проверено автоподбором), поэтому он в VPN.", "These domains resolve directly and leave via WAN through the nfqws queue — bypassing VPN. Discord is intentionally not here: on this line DPI cuts it under every tested nfqws strategy, so it goes through the VPN.")}</p>
            <textarea className="w-full h-48 rounded border bg-background p-2 font-mono text-xs" value={draft.tier2.domains.join("\n")} onChange={(e) => setText({ tier2: { ...draft.tier2, domains: e.target.value.split("\n") } })} />
            <label className="text-xs text-muted-foreground">{L("Статичные CIDR мимо VPN (Meta-рёбра и т.п.)", "Static CIDRs bypassing VPN (Meta edges etc.)")}</label>
            <textarea className="w-full h-16 rounded border bg-background p-2 font-mono text-xs" value={(draft.tier2.networks || []).join("\n")} onChange={(e) => setText({ tier2: { ...draft.tier2, networks: e.target.value.split("\n") } })} />
          </CardContent>
        </Card>

        <Card>
          <CardHeader><CardTitle className="flex items-center gap-2 text-base"><Server className="h-4 w-4 text-blue-500" />{L("3. VPN (весь остальной)", "3. VPN (everything else)")}</CardTitle></CardHeader>
          <CardContent className="space-y-2 text-sm">
            <div className="flex items-center justify-between">
              <span className="text-xs text-muted-foreground">{L("Catch-all в sing-box (fwmark + policy table)", "Catch-all into sing-box (fwmark + policy table)")}</span>
              <Switch checked={draft.proxyEnabled} onCheckedChange={(v) => setText({ proxyEnabled: v })} />
            </div>
            <div className="flex items-center justify-between">
              <span className="text-xs text-muted-foreground">{L("antizapret rule-set → тоже VPN", "antizapret rule-set → also VPN")}</span>
              <Switch checked={withAntizapret} onCheckedChange={setWithAntizapret} />
            </div>
            <label className="text-xs text-muted-foreground">{L("Policy table", "Policy table")}</label>
            <Input type="number" className="h-8 font-mono text-xs w-28" value={draft.routeTable} onChange={(e) => setText({ routeTable: Number(e.target.value) || draft.routeTable })} />
            <label className="text-xs text-muted-foreground">{L("Принудительно в VPN (домены)", "Forced into VPN (domains)")}</label>
            <textarea className="w-full h-16 rounded border bg-background p-2 font-mono text-xs" value={draft.tier3ExtraDomains.join("\n")} onChange={(e) => setText({ tier3ExtraDomains: e.target.value.split("\n") })} />
          </CardContent>
        </Card>
      </div>

      <p className="text-xs text-muted-foreground">
        {L("Порядок применения: генерация → самопроверка на петли/утечки DNS → загрузка частями на роутер → валидация nft -c / sh -n → бэкап → применение → проверка ядра. При ошибке ничего не применяется. Смена активного узла — по данным балансировщика (реальная скорость через узел), падение узла переключается автоматически.",
          "Apply flow: generate → self-check for loops/DNS leaks → staged upload → router validation (nft -c / sh -n) → backup → apply → kernel verification. On error nothing is applied. Active-node failover uses the real-throughput balancer.")}
      </p>
    </div>
  );
};
